import app from 'flarum/forum/app';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import AboutNav, { guidelinesEnabled } from './AboutNav';
import CommunityPage from './CommunityPage';
import { t } from '../../utils/settings';

/**
 * As "Diretrizes" do Discourse (/guidelines, e /faq como apelido): as abas do
 * Sobre e o texto, do admin ou o padrão do tema, renderizado no servidor.
 */
export default class GuidelinesPage extends CommunityPage {
  html = null;
  failed = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (this.enabled()) this.load();
  }
  title() {
    return t('community.guidelines.title');
  }
  className() {
    return 'CanelaGuidelinesPage';
  }
  enabled() {
    return guidelinesEnabled();
  }
  load() {
    app.request({
      method: 'GET',
      url: `${(app.forum.attribute('apiUrl') || '/api').replace(/\/+$/, '')}/canela-guidelines`
    }).then(data => this.html = data?.html || '').catch(() => this.failed = true).finally(() => m.redraw());
  }
  content() {
    let body;
    if (this.failed) body = m("p", {
      className: "CanelaCommunity-empty"
    }, t('community.load_error'));else if (this.html === null) body = m(LoadingIndicator, {
      display: "block"
    });
    // O texto é do admin (ou o padrão do tema), já renderizado no servidor.
    else body = m("div", {
      className: "CanelaGuidelines-body CanelaAbout-text Post-body"
    }, m.trust(this.html));
    return m("div", {
      className: "CanelaAbout CanelaGuidelines"
    }, m("header", {
      className: "CanelaAbout-header"
    }, AboutNav('canela.guidelines')), body);
  }
}
flarum.reg.add('ramon-canela', 'forum/features/community/GuidelinesPage', GuidelinesPage);